      body = new URLSearchParams("a=1");
      meta.size = 3;
      const res = await req({ range: "bytes=0-1" });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
    });

    it("falls back to 200 when contents are missing", async () => {
      body = undefined;
      const res = await req({ range: "bytes=0-1" });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
